CREATE TABLE public.tenant_verification_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, scan_id uuid NOT NULL REFERENCES public.application_scans(id), target text NOT NULL, commit_sha text NOT NULL CHECK (commit_sha ~ '^[a-f0-9]{40}$'), endpoint text NOT NULL, id_pointer text NOT NULL, rule text NOT NULL, suite_digest text NOT NULL, nonce uuid NOT NULL DEFAULT gen_random_uuid(), approved_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT (now() + interval '24 hours'), UNIQUE(id,user_id)); GRANT SELECT ON public.tenant_verification_plans TO authenticated; GRANT ALL ON public.tenant_verification_plans TO service_role; ALTER TABLE public.tenant_verification_plans ENABLE ROW LEVEL SECURITY; CREATE POLICY tenant_plan_owner_read ON public.tenant_verification_plans FOR SELECT TO authenticated USING (auth.uid()=user_id); CREATE TABLE public.tenant_verification_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, plan_id uuid NOT NULL, outcome text NOT NULL CHECK(outcome IN ('pass','fail','inconclusive')), result jsonb NOT NULL, artifact_digest text NOT NULL, provenance text NOT NULL DEFAULT 'customer-reported' CHECK(provenance='customer-reported'), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(plan_id,user_id) REFERENCES public.tenant_verification_plans(id,user_id), UNIQUE(plan_id,artifact_digest)); GRANT SELECT ON public.tenant_verification_runs TO authenticated; GRANT ALL ON public.tenant_verification_runs TO service_role; ALTER TABLE public.tenant_verification_runs ENABLE ROW LEVEL SECURITY; CREATE POLICY tenant_run_owner_read ON public.tenant_verification_runs FOR SELECT TO authenticated USING(auth.uid()=user_id); CREATE INDEX tenant_plan_owner_time ON public.tenant_verification_plans(user_id,approved_at DESC); CREATE INDEX tenant_run_owner_time ON public.tenant_verification_runs(user_id,created_at DESC);